INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_021_M01', 'Dynamic Force Analysis', '1', 'Dynamic Force Analysis examines Flywheels within Dynamics of Machines. Key technical concerns include Energy storage, inertia, speed regulation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DYNAMIC_FORCE_ANALYSIS', 'Active'), ('MOD_COURSE_021_M02', 'Balancing', '2', 'Balancing examines Static and dynamic balancing within Dynamics of Machines. Key technical concerns include Force balance, moment balance, vibration reduction, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_BALANCING', 'Active'), ('MOD_COURSE_021_M03', 'Free Vibration', '3', 'Free Vibration examines Natural frequency within Dynamics of Machines. Key technical concerns include Inertia, stiffness, modal behaviour, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FREE_VIBRATION', 'Active'), ('MOD_COURSE_021_M04', 'Forced Vibration', '4', 'Forced Vibration examines Resonance within Dynamics of Machines. Key technical concerns include Dynamic amplification, frequency matching, damping, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FORCED_VIBRATION', 'Active'), ('MOD_COURSE_021_M05', 'Governors & Gyroscopes', '5', 'Governors & Gyroscopes examines Governor and gyroscope principles within Dynamics of Machines. Key technical concerns include Feedback/regulation, angular momentum, dynamic stability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GOVERNORS_GYROSCOPES', 'Active'), ('MOD_COURSE_022_M01', 'Casting', '1', 'Casting examines Sand casting within Manufacturing Processes. Key technical concerns include Material shaping, solidification, resource use, process quality, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CASTING', 'Active'), ('MOD_COURSE_022_M02', 'Metal Forming', '2', 'Metal Forming examines Forging within Manufacturing Processes. Key technical concerns include Plastic deformation, material integrity, grain flow, energy input, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_METAL_FORMING', 'Active'), ('MOD_COURSE_022_M03', 'Joining Processes', '3', 'Joining Processes examines Arc welding within Manufacturing Processes. Key technical concerns include Fusion, heat transfer, metallurgical control, joint integrity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_JOINING_PROCESSES', 'Active'), ('MOD_COURSE_022_M04', 'Machining', '4', 'Machining examines Lathe operations within Manufacturing Processes. Key technical concerns include Material removal, geometric accuracy, cutting mechanics, productivity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MACHINING', 'Active'), ('MOD_COURSE_022_M05', 'Non-traditional Machining', '5', 'Non-traditional Machining examines Electrical discharge machining within Manufacturing Processes. Key technical concerns include Localized energy transfer, material removal, process control, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_NON_TRADITIONAL_MACHINING', 'Active'), ('MOD_COURSE_023_M01', 'Failure Theories', '1', 'Failure Theories examines Von Mises within Design of Machine Elements. Key technical concerns include Distortion energy, yielding, multiaxial stress, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FAILURE_THEORIES', 'Active'), ('MOD_COURSE_023_M02', 'Fatigue Design', '2', 'Fatigue Design examines Goodman diagram within Design of Machine Elements. Key technical concerns include Fatigue, mean-stress effect, safety factor, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FATIGUE_DESIGN', 'Active'), ('MOD_COURSE_023_M03', 'Shafts & Keys', '3', 'Shafts & Keys examines Shaft and key design within Design of Machine Elements. Key technical concerns include Strength, stiffness, fatigue, torque transmission, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SHAFTS_KEYS', 'Active'), ('MOD_COURSE_023_M04', 'Springs & Bearings', '4', 'Springs & Bearings examines Journal bearings within Design of Machine Elements. Key technical concerns include Lubrication, friction reduction, load capacity, thermal management, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SPRINGS_BEARINGS', 'Active'), ('MOD_COURSE_023_M05', 'Gears', '5', 'Gears examines Gear design fundamentals within Design of Machine Elements. Key technical concerns include Power transmission, strength, wear, reliability, geometry, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GEARS', 'Active'), ('MOD_COURSE_024_M01', 'System Modeling', '1', 'System Modeling examines Laplace transforms within Control Systems Engineering. Key technical concerns include Linear systems, superposition, transform-domain analysis, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SYSTEM_MODELING', 'Active'), ('MOD_COURSE_024_M02', 'Time Domain Analysis', '2', 'Time Domain Analysis examines Time-domain response within Control Systems Engineering. Key technical concerns include Stability, transient performance, steady-state accuracy, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TIME_DOMAIN_ANALYSIS', 'Active'), ('MOD_COURSE_024_M03', 'Stability', '3', 'Stability examines Routh-Hurwitz and Nyquist criteria within Control Systems Engineering. Key technical concerns include Stability, pole location, feedback, robustness, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_STABILITY', 'Active'), ('MOD_COURSE_024_M04', 'Frequency Domain Analysis', '4', 'Frequency Domain Analysis examines Bode plot within Control Systems Engineering. Key technical concerns include Frequency response, stability margins, bandwidth, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FREQUENCY_DOMAIN_ANALYSIS', 'Active'), ('MOD_COURSE_024_M05', 'Controller Design', '5', 'Controller Design examines PID control within Control Systems Engineering. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for PID control, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONTROLLER_DESIGN', 'Active'), ('MOD_COURSE_025_M1', 'Intelligent Agents', '1', 'Examines the concepts and methods required to understand and work with intelligent agents. The module addresses agents and environments, rational action, agent architectures, and utility and performance measures, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M1', 'Active'), ('MOD_COURSE_025_M2', 'Problem Solving and Search', '2', 'Examines the concepts and methods required to understand and work with problem solving and search. The module addresses state-space formulation, uninformed search, heuristic search, local search, and adversarial search, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M2', 'Active'), ('MOD_COURSE_025_M3', 'Knowledge Representation and Reasoning', '3', 'Examines the concepts and methods required to understand and work with knowledge representation and reasoning. The module addresses propositional logic, first-order logic, ontologies, knowledge graphs, inference, and reasoning under uncertainty, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M3', 'Active'), ('MOD_COURSE_025_M4', 'Planning and Decision Making', '4', 'Examines the concepts and methods required to understand and work with planning and decision making. The module addresses classical planning, partial-order planning, probabilistic decision making, Markov decision processes, and sequential decision making, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M4', 'Active'), ('MOD_COURSE_025_M5', 'Machine Learning Foundations', '5', 'Establishes the foundational models, terminology, and governing principles machine learning foundations. The module addresses learning paradigms, hypothesis spaces, feature representations, generalization, bias-variance, and learning pipelines, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M5', 'Active'), ('MOD_COURSE_025_M6', 'Natural Language Processing', '6', 'Examines the concepts and methods required to understand and work with natural language processing. The module addresses text representation, language models, sequence modelling, parsing, information extraction, and evaluation, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M6', 'Active'), ('MOD_COURSE_025_M7', 'Computer Vision and Perception', '7', 'Examines the concepts and methods required to understand and work with computer vision and perception. The module addresses image formation, feature extraction, classification, object detection, segmentation, and evaluation, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M7', 'Active'), ('MOD_COURSE_025_M8', 'AI Systems, Safety and Ethics', '8', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance ai systems, safety and ethics. The module addresses AI system architecture, robustness, interpretability, fairness, privacy, and safety and governance, with emphasis on their relationships, assumptions, analytical use, and application within Artificial Intelligence.', 'MSD_COURSE_025_M8', 'Active'), ('MOD_COURSE_026_M1', 'Learning Paradigms', '1', 'Examines the concepts and methods required to understand and work with learning paradigms. The module addresses supervised learning, unsupervised learning, semi-supervised learning, self-supervised learning, and reinforcement learning, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M1', 'Active'), ('MOD_COURSE_026_M2', 'Data Preparation and Feature Engineering', '2', 'Examines the concepts and methods required to understand and work with data preparation and feature engineering. The module addresses data cleaning, missing values, categorical encoding, scaling, feature selection, and leakage control, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M2', 'Active'), ('MOD_COURSE_026_M3', 'Regression and Classification', '3', 'Examines the concepts and methods required to understand and work with regression and classification. The module addresses linear regression, logistic regression, regularization, decision trees, ensemble methods, and support vector machines, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M3', 'Active'), ('MOD_COURSE_026_M4', 'Probabilistic and Bayesian Learning', '4', 'Examines the concepts and methods required to understand and work with probabilistic and bayesian learning. The module addresses probability models, Bayes rule, naive Bayes, graphical models, maximum likelihood, and Bayesian inference, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M4', 'Active'), ('MOD_COURSE_026_M5', 'Unsupervised Learning and Representation', '5', 'Examines the concepts and methods required to understand and work with unsupervised learning and representation. The module addresses clustering, dimensionality reduction, principal component analysis, mixture models, and manifold learning, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M5', 'Active'), ('MOD_COURSE_026_M6', 'Neural Networks and Deep Learning', '6', 'Examines the concepts and methods required to understand and work with neural networks and deep learning. The module addresses perceptrons, multilayer networks, backpropagation, convolutional networks, sequence models, and optimization, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M6', 'Active'), ('MOD_COURSE_026_M7', 'Model Evaluation and Deployment', '7', 'Develops the analytical methods used to formulate, solve, and evaluate problems model evaluation and deployment. The module addresses cross-validation, calibration, imbalanced data, hyperparameter selection, model monitoring, and reproducibility, with emphasis on their relationships, assumptions, analytical use, and application within Machine Learning.', 'MSD_COURSE_026_M7', 'Active'), ('MOD_COURSE_027_M1', 'Distributed System Models', '1', 'Examines the concepts and methods required to understand and work with distributed system models. The module addresses system models, communication models, time and ordering, failure models, and scalability, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M1', 'Active'), ('MOD_COURSE_027_M2', 'Communication and Coordination', '2', 'Examines the mechanisms used to regulate, coordinate, or control system behaviour communication and coordination. The module addresses RPC, messaging, multicast, logical clocks, leader election, and distributed coordination, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M2', 'Active'), ('MOD_COURSE_027_M3', 'Replication and Consistency', '3', 'Examines the concepts and methods required to understand and work with replication and consistency. The module addresses primary-backup replication, quorum systems, consistency models, consensus, and conflict resolution, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M3', 'Active'), ('MOD_COURSE_027_M4', 'Distributed Transactions', '4', 'Examines the concepts and methods required to understand and work with distributed transactions. The module addresses atomic commit, two-phase commit, distributed concurrency control, serializability, and recovery, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M4', 'Active'), ('MOD_COURSE_027_M5', 'Distributed Storage', '5', 'Examines the concepts and methods required to understand and work with distributed storage. The module addresses partitioning, distributed hash tables, distributed file systems, object storage, and metadata management, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M5', 'Active'), ('MOD_COURSE_027_M6', 'Fault Tolerance and Recovery', '6', 'Examines the concepts and methods required to understand and work with fault tolerance and recovery. The module addresses failure detection, redundancy, checkpointing, recovery protocols, and Byzantine failures, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M6', 'Active'), ('MOD_COURSE_027_M7', 'Distributed System Design', '7', 'Develops the design methods and decision criteria used to translate theory into an engineered or applied solution distributed system design. The module addresses availability, partition tolerance, load balancing, observability, and performance trade-offs, with emphasis on their relationships, assumptions, analytical use, and application within Distributed Systems.', 'MSD_COURSE_027_M7', 'Active'), ('MOD_COURSE_028_M1', 'Cloud Computing Models', '1', 'Examines the concepts and methods required to understand and work with cloud computing models. The module addresses IaaS, PaaS, SaaS, public/private/hybrid cloud, and shared responsibility, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M1', 'Active'), ('MOD_COURSE_028_M2', 'Virtualization Technologies', '2', 'Examines the concepts and methods required to understand and work with virtualization technologies. The module addresses hypervisors, virtual machines, containers, hardware virtualization, and resource isolation, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M2', 'Active'), ('MOD_COURSE_028_M3', 'Cloud Resource Management', '3', 'Examines the concepts and methods required to understand and work with cloud resource management. The module addresses provisioning, autoscaling, scheduling, resource allocation, and capacity planning, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M3', 'Active'), ('MOD_COURSE_028_M4', 'Cloud Storage and Data Services', '4', 'Examines the concepts and methods required to understand and work with cloud storage and data services. The module addresses object storage, block storage, file storage, distributed databases, and data durability, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M4', 'Active'), ('MOD_COURSE_028_M5', 'Cloud Networking', '5', 'Examines the concepts and methods required to understand and work with cloud networking. The module addresses virtual networks, subnets, routing, load balancing, service discovery, and network security, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M5', 'Active'), ('MOD_COURSE_028_M6', 'Cloud Orchestration and Automation', '6', 'Examines the concepts and methods required to understand and work with cloud orchestration and automation. The module addresses infrastructure as code, configuration management, orchestration, service deployment, and autoscaling policies, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M6', 'Active'), ('MOD_COURSE_028_M7', 'Cloud Security and Reliability', '7', 'Examines the concepts and methods required to understand and work with cloud security and reliability. The module addresses identity and access management, encryption, isolation, resilience, and backup and disaster recovery, with emphasis on their relationships, assumptions, analytical use, and application within Cloud Computing and Virtualization.', 'MSD_COURSE_028_M7', 'Active'), ('MOD_COURSE_029_M1', 'Data Center Architecture and Facilities', '1', 'Examines how the relevant components are organised into functioning systems and how their interactions constrain performance data center architecture and facilities. The module addresses site planning, rack layout, power distribution, cooling architecture, and physical security, with emphasis on their relationships, assumptions, analytical use, and application within Data Center Operations and Infrastructure.', 'MSD_COURSE_029_M1', 'Active') ON CONFLICT DO NOTHING;